import {p,e,r,star,cloud,leaf,flower,line,board} from './coloring-shapes.js';
const advanced=(id,name,price,description,shapes,ink='')=>board(id,name,'进阶画板',price,description,shapes,ink);
// Each facet is a real, closed color region; no hidden base shape underneath.
const gem=(name,x,y,w,h)=>{
 const ring=Array.from({length:8},(_,i)=>{const a=-Math.PI/2+i*Math.PI/4;return [x+Math.cos(a)*w,y+Math.sin(a)*h];});
 const inner=ring.map(([a,b])=>[x+(a-x)*.48,y+(b-y)*.48]);
 const shape=points=>'M'+points.map(pt=>pt.map(v=>v.toFixed(2)).join(' ')).join('L')+'Z';
 return [...ring.map((pt,i)=>p(`${name}切面${i+1}`,shape([pt,ring[(i+1)%8],inner[(i+1)%8],inner[i]]))),p(`${name}宝石心`,shape(inner))];
};
const pine=(name,x,y,s=1)=>[r(`${name}树干`,x-5*s,y,10*s,70*s,3),...Array.from({length:3},(_,i)=>p(`${name}枝叶${i+1}`,`M${x} ${y-70*s+i*29*s}L${x-(24+i*6)*s} ${y-14*s+i*29*s}Q${x} ${y-5*s+i*29*s} ${x+(24+i*6)*s} ${y-14*s+i*29*s}Z`))];
